        require(address(this).balance >= amount);

        // Deposit Ether into c: this is a plain top-level external call on the payable address,
        // which triggers c's receive() and increases c's balance.
        (bool depositOk, ) = address(c).call{value: amount}("");
        require(depositOk);

        uint cBalanceBefore = address(c).balance;
        uint callerBalanceBefore = address(this).balance;

        // Deciding call: withdrawAll by the owner (this contract).
        c.withdrawAll();

        uint cBalanceAfter = address(c).balance;
        uint callerBalanceAfter = address(this).balance;

        assert(cBalanceAfter == 0 && callerBalanceAfter == callerBalanceBefore + cBalanceBefore);
