        c = _c;
    }

    receive() external payable {}

    function run(uint256 v) public payable {
        address ownerBefore = c.owner();
        uint256 depositsBefore = c.depositsCount();

        require(msg.sender == ownerBefore, "caller must be owner");

        uint256 cBalanceBefore = address(c).balance;
        bool reverted;
        try c.withdraw(v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalanceAfter = address(c).balance;
        uint256 depositsAfter = c.depositsCount();
        address ownerAfter = c.owner();

        assert(
            (reverted == (v > cBalanceBefore)) &&
            (reverted || (cBalanceAfter == cBalanceBefore - v)) &&
            (depositsAfter == depositsBefore) &&
            (ownerAfter == ownerBefore)
        );
    }
}

